<div class="report-summary-grid"><article class="report-stat"><span>Total transaksi</span><strong><?= number_format((int) $summary['totals']['transaction_count'], 0, ',', '.') ?></strong><small>Jumlah baris transaksi</small></article><article class="report-stat"><span>Nilai beli valas</span><strong><?= mc_e(mc_money($summary['totals']['buy_idr'])) ?></strong><small>Ekuivalen IDR</small></article><article class="report-stat"><span>Nilai jual valas</span><strong><?= mc_e(mc_money($summary['totals']['sell_idr'])) ?></strong><small>Ekuivalen IDR</small></article><article class="report-stat highlight-stat"><span>Total profit terhitung</span><strong><?= mc_e(mc_money($summary['totals']['total_profit_idr'])) ?></strong><small>Σ (kurs jual − kurs beli) × valas</small></article><article class="report-stat"><span>Total buffer</span><strong><?= mc_e(mc_money($summary['totals']['total_buffer'])) ?></strong><small>Akumulasi buffer yang diinput</small></article></div>
<section class="panel"><div class="panel-heading"><div><h2>Profit per Mata Uang</h2><p>Profit dihitung dari selisih kurs beli dan jual dikalikan nominal valas.</p></div></div><?php if (!$summary['by_currency']): ?><div class="empty-state"><span class="empty-icon">▤</span><strong>Belum ada data untuk direkap</strong><p>Silakan ubah rentang tanggal atau filter laporan.</p></div><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Mata uang</th><th>Qty transaksi</th><th class="numeric">Nominal valas</th><th class="numeric">Rata-rata selisih rate</th><th class="numeric">Beli (IDR)</th><th class="numeric">Jual (IDR)</th><th class="numeric">Profit (IDR)</th><th class="numeric">Buffer (IDR)</th></tr></thead><tbody><?php foreach ($summary['by_currency'] as $row): ?><tr><td><div class="currency-title"><strong><?= mc_e($row['currency_code']) ?></strong><span><?= mc_e($row['currency_name']) ?></span></div></td><td><?= number_format((int) $row['transaction_count'], 0, ',', '.') ?></td><td class="numeric"><?= mc_e(mc_number($row['total_currency'], 2)) ?> <?= mc_e($row['currency_code']) ?></td><td class="numeric"><?= mc_e(mc_money($row['average_spread_rate'])) ?></td><td class="numeric"><?= mc_e(mc_money($row['buy_idr'])) ?></td><td class="numeric"><?= mc_e(mc_money($row['sell_idr'])) ?></td><td class="numeric strong-cell"><?= mc_e(mc_money($row['profit_idr'])) ?></td><td class="numeric"><?= mc_e(mc_money($row['buffer_amount'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="panel"><div class="panel-heading"><div><h2>Sales by User</h2><p>Jumlah transaksi jual, nominal valas, nilai IDR, dan estimasi profit per pengguna.</p></div></div><?php if (empty($summary['sales_by_user'])): ?><div class="empty-state compact-empty"><strong>Belum ada transaksi jual pada rentang ini.</strong></div><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Nama user</th><th>Mata uang</th><th class="numeric">Qty</th><th class="numeric">Nominal valas</th><th class="numeric">Nominal sales (IDR)</th><th class="numeric">Profit (IDR)</th></tr></thead><tbody><?php foreach ($summary['sales_by_user'] as $row): ?><tr><td><strong><?= mc_e($row['user_name']) ?></strong></td><td><?= mc_e($row['currency_code']) ?></td><td class="numeric"><?= number_format((int) $row['transaction_count'], 0, ',', '.') ?></td><td class="numeric"><?= mc_e(mc_number($row['total_currency'], 2)) ?> <?= mc_e($row['currency_code']) ?></td><td class="numeric strong-cell"><?= mc_e(mc_money($row['total_idr'])) ?></td><td class="numeric"><?= mc_e(mc_money($row['profit_idr'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="panel"><div class="panel-heading"><div><h2>Detail Transaksi</h2><p><?= number_format(count($rows), 0, ',', '.') ?> baris dalam hasil filter</p></div></div><?php if (!$rows): ?><div class="empty-state compact-empty"><p>Tidak ada detail transaksi pada filter ini.</p></div><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>TransDate</th><th>Referensi</th><th>Jenis</th><th>Valas</th><th>Pelanggan</th><th class="numeric">Nominal</th><th class="numeric">Kurs beli</th><th class="numeric">Kurs jual</th><th class="numeric">Selisih rate</th><th class="numeric">Profit IDR</th><th class="numeric">Buffer</th><th class="numeric">Total IDR</th><th>User</th></tr></thead><tbody><?php foreach ($rows as $row): $items = $transactionItems($row); $currencyLines = []; $nominalLines = []; $buyLines = []; $sellLines = []; $spreadLines = []; foreach ($items as $item) { $currencyLines[] = trim((string) ($item['currency_code'] ?? '')) . ((string) ($item['currency_name'] ?? '') !== '' ? ' · ' . trim((string) $item['currency_name']) : ''); $nominalLines[] = mc_number($item['amount_currency'] ?? 0, 2); $buyLines[] = mc_number($item['buy_rate'] ?? 0, 2); $sellLines[] = mc_number($item['sell_rate'] ?? 0, 2); $spreadLines[] = mc_money((float) ($item['sell_rate'] ?? 0) - (float) ($item['buy_rate'] ?? 0)); } ?><tr><td><?= mc_e(date('d/m/Y H:i', strtotime($row['transaction_datetime'] ?? $row['transaction_date']))) ?></td><td><span class="reference-code"><?= mc_e($row['reference_no']) ?></span></td><td><?= mc_e($row['transaction_type'] === 'BUY' ? 'Beli' : 'Jual') ?></td><td><?= $stackLines($currencyLines) ?></td><td><?= mc_e($row['customer_name'] ?: '—') ?></td><td class="numeric"><?= $stackLines($nominalLines, 'align-right') ?></td><td class="numeric"><?= $stackLines($buyLines, 'align-right') ?></td><td class="numeric"><?= $stackLines($sellLines, 'align-right') ?></td><td class="numeric"><?= $stackLines($spreadLines, 'align-right') ?></td><td class="numeric strong-cell"><?= mc_e(mc_money($row['profit_idr'])) ?></td><td class="numeric"><?= mc_e(mc_money($row['buffer_amount'])) ?></td><td class="numeric"><?= mc_e(mc_money($row['amount_idr'])) ?></td><td><?= mc_e($row['creator_name'] ?? '—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
